-- Bank change concentration demo (805): one operator replaced six bank accounts in six days with no approval reference
SELECT gen_random_uuid(), '50000005-0000-0000-0000-000000000001', 'bank_token', 'old' || g, 'new' || g, 'OP-DEMO-805', NULL, NOW() - (g || ' days')::interval
FROM generate_series(1, 6) g
WHERE NOT EXISTS (SELECT 1 FROM master_change_log WHERE operator_id = 'OP-DEMO-805' LIMIT 1);

-- An approved batch migration, bigger than that: its approval reference starts with BATCH-, so 805 leaves it out
SELECT gen_random_uuid(), '5000000a-0000-0000-0000-' || lpad(g::text, 12, '0'), 'bank_token', 'old' || g, 'new' || g, 'OP-DEMO-MIGRATION', 'BATCH-MIG-2024', NOW() - (g || ' days')::interval
FROM generate_series(1, 8) g
WHERE NOT EXISTS (SELECT 1 FROM master_change_log WHERE operator_id = 'OP-DEMO-MIGRATION' LIMIT 1);

